  { id: "section-4", lv: "Jāzeps Grosvalds",  en: "Jazeps Grosvalds",  birth: 1891, death: 1920 },
  { id: "section-5", lv: "Kārlis Padegs",     en: "Karlis Padegs",     birth: 1911, death: 1940 },
