    await expect(lightbox).toHaveAttribute("aria-hidden", "true");
    await expect(lightbox).not.toHaveClass(/is-open/);
  });

  test("active dot in sticky header tracks scroll position", async ({ page }) => {
    await reduceMotion(page);
